using System.ComponentModel.DataAnnotations;
namespace WanderXServer.Dtos.Dashboard;
public sealed class DashboardQuery { public DateTime? FromDate { get; set; } public DateTime? ToDate { get; set; } public string? TourCode { get; set; } public string? Destination { get; set; } public string? Status { get; set; } [Range(1, int.MaxValue)] public int Page { get; set; }=1; [Range(1,50)] public int PageSize { get; set; }=10; }
public sealed class DashboardSummary { public DateTime FromDate { get; set; } public DateTime ToDate { get; set; } public DateTime LastUpdated { get; set; } public string TimeZone { get; set; }="Asia/Ho_Chi_Minh"; public int OpenTourCount { get; set; } public int BookingCount { get; set; } public decimal ExpectedRevenue { get; set; } public decimal CollectedRevenue { get; set; } public decimal OutstandingRevenue { get; set; } public string Currency { get; set; }="VND"; }
public sealed class BookingStatusPoint { public DateTime Date { get; set; } public string Status { get; set; }=string.Empty; public int Count { get; set; } }
public sealed class RevenueByTourItem { public string TourCode { get; set; }=string.Empty; public string TourName { get; set; }=string.Empty; public decimal Expected { get; set; } public decimal Collected { get; set; } public decimal Outstanding { get; set; } }
public sealed class RevenueByTourPage { public int Page { get; set; } public int PageSize { get; set; } public int TotalCount { get; set; } public decimal TotalExpected { get; set; } public decimal TotalCollected { get; set; } public List<RevenueByTourItem> Items { get; set; }=new(); }
public sealed class TopGuideItem { public int Rank { get; set; } public Guid GuideId { get; set; } public string GuideName { get; set; }=string.Empty; public int CompletedTours { get; set; } public double? AverageRating { get; set; } public int ReviewCount { get; set; } public double AcceptanceRate { get; set; } public double Score { get; set; } public string RatingNote { get; set; }=string.Empty; public List<string> ScoreBreakdown { get; set; }=new(); }